require_once __DIR__.'/qrcode.php';
function invoice_logo_path(array $brand): string {$path=$brand['shop_logo']??'';if(!is_string($path)||!preg_match('~^[a-zA-Z0-9_./ -]+\.(?:png|jpe?g|webp|gif)$~iD',$path)||str_contains($path,'..'))return '';$root=realpath(BASE_DIR.'/uploads');$real=realpath(BASE_DIR.'/uploads/'.$path);return $root&&$real&&str_starts_with($real,$root.DIRECTORY_SEPARATOR)?BASE_URL.'uploads/'.implode('/',array_map('rawurlencode',explode('/',$path))):'';}
function invoice_print_amount(array $sale,array $line,string $field,bool $sample=false,int $digits=2): string {if($sample)return ui_number($line[$field]??0,$digits,true);$text=currency_historical_format($line===$sale?'sales':'sale_items',(int)($line['id']??0),$field,$line[$field]??0,$digits,false);if($digits>2){$text=preg_replace('/[0۰]+$/u','',$text);$text=preg_replace('/[.٫]$/u','',$text);}return $text;}
function invoice_preview_data(array $layout): array {$sale=['id'=>0,'invoice_no'=>'PREVIEW-001','created_at'=>date('Y-m-d H:i:s'),'customer_name'=>__t('Sample customer','مشتری نمونه','نمونه پیرودونکی'),'customer_phone'=>'+93 700 000 000','payment_type'=>'نقد','total_amount'=>'2500.00','paid_amount'=>'2500.00','remaining_amount'=>'0.00','notes'=>'','currency_code'=>'AFN'];$fields=[];foreach($layout['columns'] as $c)if($c['source']==='custom')$fields[$c['id']]=__t('Sample value','مقدار نمونه','نمونه ارزښت');$items=[['id'=>0,'product_name'=>__t('Sample product','جنس نمونه','نمونه توکی'),'specifications'=>__t('Model and colour','مدل و رنگ','ماډل او رنګ'),'quantity'=>'2.000','unit'=>'unit','unit_sale_price'=>'1250.000000','total_price'=>'2500.00','invoice_fields'=>json_encode($fields,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR)]];return [$sale,$items];}
function invoice_render(array $sale,array $items,array $brand,array $layout,bool $sample=false,bool $word=false): void {
 $layout=invoice_layout_validate($layout);$logoValue=$brand['shop_logo']??'';$brand=invoice_brand_validate($brand,invoice_default_brand());$brand['shop_logo']=$logoValue;$dir=get_current_dir();$lang=get_current_lang();$code=$sale['currency_code']??currency_base_code();$format=$brand['invoice_format'];$format=$format==='doc'?'a5':$format;$thermal=$format==='thermal';$orientation=$thermal?'portrait':$brand['invoice_orientation'];$accent=$brand['invoice_accent_color'];$logo=invoice_logo_path($brand);$font=$layout['font_size'];$spacing=['compact'=>'5px','normal'=>'8px','relaxed'=>'12px'][$layout['spacing']];$paper=$thermal?'80mm 200mm':strtoupper($format).' '.$orientation;
 $verifyUrl=$sample?null:invoice_verification_url($sale);$qrSize=$verifyUrl?max(24,round((nik_qr_matrix($verifyUrl,'M')['size']+8)*0.44,1)):24;$qr=$verifyUrl?nik_qr_svg($verifyUrl,['size_mm'=>$qrSize]):'';
 $money=fn($line,$field,$digits=2)=>invoice_print_amount($sale,$line,$field,$sample,$digits);
 $columns=$layout['columns'];$thermalDetails=[];if($thermal&&count($columns)>5){$thermalDetails=array_values(array_filter($columns,fn($c)=>in_array($c['source'],['custom','specifications'],true)));$columns=array_values(array_filter($columns,fn($c)=>!in_array($c['source'],['custom','specifications','number'],true)));}
 $title=$brand['invoice_title']?:__t('Sales invoice','بل فروش','د پلور بل');
 ?>
