@page{size:<?= $paper ?>;margin:<?= $thermal?'3mm':'9mm' ?>}*{box-sizing:border-box}body{margin:0;padding:18px;background:#edf1f6;color:#162033;font-family:Vazirmatn,Arial,sans-serif;font-size:<?= $font ?>px;line-height:1.6}.print-toolbar{display:flex;gap:8px;flex-wrap:wrap;justify-content:center;margin:0 auto 14px}.print-toolbar a,.print-toolbar button{font:inherit;padding:9px 14px;border:1px solid #cbd5e1;border-radius:9px;background:white;color:#162033;text-decoration:none;cursor:pointer}.invoice{width:<?= $thermal?'74mm':($format==='a4'?($orientation==='landscape'?'277mm':'192mm'):($orientation==='landscape'?'192mm':'130mm')) ?>;max-width:100%;margin:auto;background:white;padding:<?= $thermal?'3mm':'7mm' ?>;border:1px solid #dbe3ef;border-radius:10px;position:relative;overflow-wrap:anywhere}.invoice-inner{position:relative}.invoice-section{margin-block:0 <?= $spacing ?>;text-align:start;break-inside:avoid}.invoice-section[data-align=center]{text-align:center}.invoice-section[data-align=end]{text-align:end}.invoice-section h1{font-size:<?= $thermal?'20':'25' ?>px;margin:0;color:<?= sanitize($accent) ?>}.invoice-section h2{font-size:<?= $font+2 ?>px;margin:2px 0 5px}.invoice-section p{margin:3px 0}.invoice-logo{max-width:84px;max-height:64px;object-fit:contain}.logo-right{text-align:right}.logo-center{text-align:center}.logo-left{text-align:left}.invoice-meta{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px 12px;border-block:1px solid #e2e8f0;padding:8px 0}.invoice-meta strong{display:block}.invoice-table{width:100%;border-collapse:collapse;table-layout:fixed;font-size:inherit}.invoice-table th,.invoice-table td{padding:<?= $spacing ?> 4px;border-bottom:1px solid #dbe3ef;text-align:inherit;vertical-align:top;word-break:normal;overflow-wrap:anywhere}.invoice-table th{background:#f1f5f9;color:<?= sanitize($accent) ?>;font-weight:700}.invoice-table thead{display:table-header-group}.invoice-table tr{break-inside:avoid}.invoice-sum{border:1px solid #dbe3ef;border-inline-start:4px solid <?= sanitize($accent) ?>;padding:10px;border-radius:6px}.invoice-sum>div{display:flex;gap:12px;justify-content:space-between}.invoice-sum .grand-total{font-size:<?= $font+3 ?>px;font-weight:800;color:<?= sanitize($accent) ?>}.invoice-muted{color:#475569;font-size:<?= max(9,$font-1) ?>px}.invoice-signatures{display:flex;justify-content:space-between;align-items:end;gap:12px}.signature-space{padding-top:26px;border-bottom:1px dashed #94a3b8;min-width:80px}.invoice-qr svg{width:<?= $qrSize ?>mm;height:<?= $qrSize ?>mm}.invoice-footer{border-top:1px solid #e2e8f0;padding-top:8px;text-align:center}.invoice-block{white-space:pre-wrap;margin:8px 0}.invoice-watermark{position:absolute;width:<?= ['small'=>'35%','medium'=>'55%','large'=>'75%'][$brand['invoice_watermark_size']] ?>;max-height:65%;object-fit:contain;opacity:<?= $brand['invoice_watermark_opacity'] ?>;top:50%;left:50%;transform:translate(-50%,-50%);pointer-events:none}.invoice-preview-banner{padding:6px;text-align:center;background:#fff4d8;color:#714600;border-radius:6px;margin-bottom:10px}.return-notice{border:1px solid #b91c1c;color:#991b1b;padding:8px}.invoice.border-classic{border:2px solid <?= sanitize($accent) ?>;border-radius:0}.invoice.border-minimal{border:0;border-radius:0}.invoice-section[data-section=items]{break-inside:auto}<?= $thermal?'.invoice-meta{grid-template-columns:1fr}.invoice{font-size:10px}.invoice-table th,.invoice-table td{padding:5px 2px}.invoice-signatures{flex-wrap:wrap}':'' ?>
