<?php if($brand['invoice_show_whatsapp']==='1'&&$brand['shop_phone_whatsapp']):?><p><?= __t('WhatsApp','واتساپ','واټساپ') ?>: <?= sanitize($brand['shop_phone_whatsapp']) ?></p><?php endif ?>
<?php if($brand['shop_address_central']):?><p><?= __t('Address','آدرس','پته') ?>: <?= sanitize($brand['shop_address_central']) ?></p><?php endif ?><?php if($brand['invoice_show_address_secondary']==='1'&&$brand['shop_address_secondary']):?><p><?= sanitize($brand['shop_address_secondary']) ?></p><?php endif ?>
