<?php foreach($items as $index=>$line):$values=json_decode($line['invoice_fields']??'{}',true)?:[];?><tr><?php foreach($columns as $c):?><td data-field="<?= sanitize($c['id']) ?>"><?php switch($c['source']){case 'number':echo sanitize(ui_number($index+1,0));break;case 'product':echo sanitize($line['product_name']);foreach($thermalDetails as $extra){$v=$extra['source']==='custom'?($values[$extra['id']]??''):($line['specifications']??'');if($v!=='')echo '<div class="invoice-muted">'.sanitize(invoice_column_label($extra).': '.$v).'</div>';}break;case 'specifications':echo sanitize($line['specifications']??'');break;case 'quantity':echo display_qty_unit($line['quantity'],$line['unit']??'unit');break;case 'unit_price':echo $money($line,'unit_sale_price',6);break;case 'total':echo $money($line,'total_price');break;case 'custom':echo sanitize($values[$c['id']]??'');break;}?></td><?php endforeach ?></tr><?php endforeach ?></tbody></table>
